//! 🧮️ Array cursor of the retained clone contract: the fixed array cursor with its default, cursor and retained clone implementations. See [`super`].

use super::*;

#[path="🔎️selection/🦀️.rs"]
mod selection;
pub use selection::{ArrayPrefixSelection,ArrayPrefixShape,select_array_prefix};

/// 📃️ Clones bounded bitwise pages or typed rows; only slots before `index` own initialized values until the final paid array move resets that prefix.
pub struct ArrayCursor<T: RetainedClone, const N: usize> {
    pub(super) prefix: NativeArrayPrefix<T,N>,
    pub(super) child: ManuallyDrop<Option<T::Cursor>>,
    pub(super) child_value: ManuallyDrop<Option<T>>,
    child_closing: bool,
    pub(super) source: ManuallyDrop<Option<RetainedCloneBinding>>,
    pub(super) output: ManuallyDrop<Option<[T; N]>>,
    pub(super) spent: bool,
    pub(super) closing: bool,
    pub(super) close: RetainedCloneClose,
    close_route:Option<(crate::OriginalEffectInvocationIdentity,u8,usize,Option<(crate::NativeAllocationIdentity,Option<u64>,crate::OriginalWorkBindingIdentity)>)>,
    advance_route:Option<(crate::OriginalEffectInvocationIdentity,usize,usize,u64,(u64,usize,usize,usize))>,
    copy_reply:ManuallyDrop<Option<Result<RetainedCloneStep,ValueError>>>,
}

impl<T: RetainedClone, const N: usize> Default for ArrayCursor<T, N> {
    fn default() -> Self {
        Self { prefix: NativeArrayPrefix::new(), child: ManuallyDrop::new(None), child_value: ManuallyDrop::new(None), child_closing: false, source: ManuallyDrop::new(None), output: ManuallyDrop::new(None), spent: false, closing: false, close: RetainedCloneClose::default(), close_route:None, advance_route:None, copy_reply:ManuallyDrop::new(None) }
    }
}


impl<T:RetainedClone,const N:usize> ArrayCursor<T,N>{
 fn prefix_selection(&self,body:usize,maximum:u64)->Result<semio_framework_value_clone_selection::ArrayPrefixSelection,ValueError>{semio_framework_value_clone_selection::select_array_prefix(semio_framework_value_clone_selection::ArrayPrefixShape{length:N,index:self.prefix.initialized(),element_bytes:size_of::<T>(),index_bytes:size_of::<usize>(),binding_work:RetainedCloneRef::<[T;N]>::check_binding_work(&self.source)},body,maximum)}
 fn whole_copy(&self,body:usize)->bool{self.prefix.is_empty()&&N<=RETAINED_CLONE_BULK_PAGE_ITEMS&&size_of::<[T;N]>()<=RETAINED_CLONE_BULK_PAGE_BYTES&&size_of::<[T;N]>()<=body}
}
impl<T: RetainedClone, const N: usize> RetainedCloneCursor<[T; N]> for ArrayCursor<T, N> {
 fn native_terminal_release(&self)->Option<RetainedCursorRelease<Self>>{Some(unsafe{RetainedCursorRelease::native(|cursor:&Self|cursor.terminal_is_empty())})}
 fn requires_original_birth(&self)->bool{if self.close_route.is_some(){return false}if let Some(child)=self.child.as_ref(){return child.requires_original_birth()}if !self.close.is_empty(){return self.close.requires_original_birth()}if self.child_value.is_some()||!self.prefix.is_empty()||self.output.is_some(){false}else{RetainedCloneBinding::requires_original_birth(&self.source)}}
 fn close_original_birth_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->crate::OriginalRetirementPoll{if let Some(child)=self.child.as_mut(){return child.close_original_birth_step(original,grant)}if !self.close.is_empty(){return self.close.step_original_birth(original,grant)}if self.child_value.is_some()||!self.prefix.is_empty(){return crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(ValueError::invariant("array Birth is not selected").into()),work:0})}if self.output.is_some(){crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(ValueError::invariant("original Birth is not the selected cursor frontier").into()),work:0})}else{RetainedCloneBinding::close_original_birth_step(&mut self.source,original,grant)}}
 fn requires_original_control(&self)->bool{if let Some((_,route,_,_))=self.close_route{return route==3||route==4}if let Some(child)=self.child.as_ref(){return child.requires_original_control()}if !self.close.is_empty(){return self.close.requires_original_control()}if self.child_value.is_some()||!self.prefix.is_empty()||self.output.is_some(){false}else{RetainedCloneBinding::requires_original_control(&self.source)}}
 fn close_into<'reply>(&mut self,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{if !self.closing{return Err(ValueError::invariant("cursor must begin close"))}if self.advance_route.is_some()||self.copy_reply.is_some(){return Err(ValueError::invariant("array original advance must settle before close"))}if self.child.is_some(){return Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"array child close producer is not yet available"))}if self.requires_original_birth()||self.requires_original_control(){return Err(ValueError::invariant("cursor requires selected original close"))}if !self.close.is_empty(){let invocation=effect.invocation().ok_or_else(||ValueError::invariant("cursor close lacks its original invocation"))?;if invocation.mode()!=crate::OriginalEffectCallbackMode::Receive{return Err(ValueError::invariant("cursor close is not its original receive invocation"))}if self.close_route.is_some(){return Err(ValueError::invariant("cursor has an unresolved original close invocation"))}let key=(invocation.identity(),1,body,None);let state=self;let mut scope=reply.progress().scope(&mut state.close_route,key)?;let done=state.close.step_into(body,effect,scope.borrow()?)?;drop(done);return Ok(scope.forwarded())}if self.child_value.is_some(){let state=self;let turn=state.close.begin_granted(&mut *state.child_value,effect);return Ok(reply.complete(turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into)))}if !self.prefix.is_empty(){let invocation=effect.invocation().ok_or_else(||ValueError::invariant("array prefix close requires original invocation"))?;if invocation.mode()!=crate::OriginalEffectCallbackMode::Receive||self.close_route.is_some(){return Err(ValueError::invariant("array prefix close invocation changed"))}let key=(invocation.identity(),5,body,None);let state=self;let mut scope=reply.progress().scope(&mut state.close_route,key)?;let inner=OriginalEffectReply::borrow(&mut state.copy_reply)?;let done=state.prefix.pop_into(&mut *state.child_value,effect,inner)?;drop(done);let forwarded=forward_original_value_reply(&mut state.copy_reply,scope.borrow()?)?;drop(forwarded);return Ok(scope.forwarded())}if self.output.is_some(){let state=self;let turn=state.close.begin_granted(&mut state.output,effect);return Ok(reply.complete(turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into)))} let invocation=effect.invocation().ok_or_else(||ValueError::invariant("cursor binding close lacks its original invocation"))?;if invocation.mode()!=crate::OriginalEffectCallbackMode::Receive{return Err(ValueError::invariant("cursor close is not its original receive invocation"))}if self.close_route.is_some(){return Err(ValueError::invariant("cursor has an unresolved original close invocation"))}let key=(invocation.identity(),2,body,None);let state=self;let mut scope=reply.progress().scope(&mut state.close_route,key)?;let done=RetainedCloneBinding::close_into(&mut state.source,body,effect,scope.borrow()?)?;drop(done);Ok(scope.forwarded())}
 fn recover_close_into<'reply>(&mut self,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{let (identity,route,selected_body,selected_original)=self.close_route.ok_or_else(||ValueError::invariant("cursor has no original close invocation"))?;let invocation=effect.invocation().ok_or_else(||ValueError::invariant("cursor close recovery lacks its original invocation"))?;if invocation.identity()!=identity||invocation.mode()!=crate::OriginalEffectCallbackMode::Recover||selected_body!=body||selected_original.is_some()||selected_body!=body||selected_original.is_some(){return Err(ValueError::invariant("cursor close recovery changed invocation"))}let state=self;let mut scope=reply.progress().scope(&mut state.close_route,(identity,route,selected_body,selected_original))?;let child=scope.borrow()?;let done=match route{1=>state.close.recover_step_into(body,effect,child),2=>RetainedCloneBinding::recover_close_into(&mut state.source,body,effect,child),5=>forward_original_value_reply(&mut state.copy_reply,child),_=>Err(ValueError::invariant("cursor close route changed"))}?;drop(done);Ok(scope.forwarded())}
 fn close_original_into<'reply>(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{if self.advance_route.is_some()||self.copy_reply.is_some(){return Err(ValueError::invariant("array original advance must settle before close"))}if self.child.is_some(){return Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"array child original close producer is not yet available"))}if self.requires_original_birth(){return Err(ValueError::invariant("cursor Birth must settle before original close"))}if !self.requires_original_control(){return self.close_into(body,effect,reply)}let invocation=effect.invocation().ok_or_else(||ValueError::invariant("cursor original close lacks invocation"))?;if !self.close.is_empty(){if invocation.mode()!=crate::OriginalEffectCallbackMode::Receive{return Err(ValueError::invariant("cursor close is not its original receive invocation"))}if self.close_route.is_some(){return Err(ValueError::invariant("cursor has an unresolved original close invocation"))}let work=original.original_work().binding_identity()?;if !work.matches_effect(effect){return Err(ValueError::invariant("cursor original close changed Work"))}let key=(invocation.identity(),3,body,Some((original.ledger_identity(),original.retirement_recipient_identity(),work)));let state=self;let mut scope=reply.progress().scope(&mut state.close_route,key)?;let done=state.close.step_original_into(original,body,effect,scope.borrow()?)?;drop(done);Ok(scope.forwarded())}else{if invocation.mode()!=crate::OriginalEffectCallbackMode::Receive{return Err(ValueError::invariant("cursor close is not its original receive invocation"))}if self.close_route.is_some(){return Err(ValueError::invariant("cursor has an unresolved original close invocation"))}let work=original.original_work().binding_identity()?;if !work.matches_effect(effect){return Err(ValueError::invariant("cursor original close changed Work"))}let key=(invocation.identity(),4,body,Some((original.ledger_identity(),original.retirement_recipient_identity(),work)));let state=self;let mut scope=reply.progress().scope(&mut state.close_route,key)?;let done=RetainedCloneBinding::close_original_into(&mut state.source,original,body,effect,scope.borrow()?)?;drop(done);Ok(scope.forwarded())}}
 fn recover_close_original_into<'reply>(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{let (identity,route,selected_body,selected_original)=self.close_route.ok_or_else(||ValueError::invariant("cursor has no original close invocation"))?;if !effect.invocation().is_some_and(|i|i.identity()==identity&&i.mode()==crate::OriginalEffectCallbackMode::Recover)||selected_body!=body{return Err(ValueError::invariant("cursor original close recovery changed invocation or body"))}if route==1||route==2||route==5{return self.recover_close_into(body,effect,reply)}let work=original.original_work().binding_identity()?;if !work.matches_effect(effect)||selected_original!=Some((original.ledger_identity(),original.retirement_recipient_identity(),work)){return Err(ValueError::invariant("cursor original close recovery changed loan"))}let state=self;let mut scope=reply.progress().scope(&mut state.close_route,(identity,route,selected_body,selected_original))?;let child=scope.borrow()?;let done=match route{3=>state.close.recover_step_original_into(original,body,effect,child),4=>RetainedCloneBinding::recover_close_original_into(&mut state.source,original,body,effect,child),_=>Err(ValueError::invariant("cursor close route changed"))}?;drop(done);Ok(scope.forwarded())}


    fn advance_into<'reply>(&mut self,source:RetainedCloneRef<'_,[T;N]>,body:usize,maximum:u64,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{
        if self.closing||self.spent{return Ok(reply.complete(Err(ValueError::invariant("array clone is closing or spent").into())))}if self.advance_route.is_some()||self.copy_reply.is_some(){return Err(ValueError::invariant("array original advance requires recovery"))}if self.output_ready(){return Ok(reply.complete(Ok(RetainedCloneStep::Complete(Default::default()))))}
        let demand=self.advance_demands(source,body,maximum)?;let work=self.advance_work_demand(source,body,maximum)?;if work==0||effect.remaining_work_units()?<work||!retained_clone_grant_admits(effect.grant(),demand){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if source.check_binding_paid(&self.source,effect).result?.is_none(){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}
        if self.source.is_none(){let turn=source.bind(&mut self.source,effect);return Ok(reply.complete(turn.result.map(|p|RetainedCloneStep::Progress(p.unwrap_or_default())).map_err(Into::into)))}
        let publish=self.prefix.initialized()==N;let whole=!publish&&self.whole_copy(body);let count=if !publish&&!whole{self.prefix_selection(body,maximum)?.elements}else{0};let invocation=effect.invocation().ok_or_else(||ValueError::invariant("array native action requires original invocation"))?;if invocation.mode()!=crate::OriginalEffectCallbackMode::Receive{return Err(ValueError::invariant("array native action requires receive invocation"))}let key=(invocation.identity(),self.prefix.initialized(),body,maximum,source.reference_identity());let mut scope=(if publish||whole{reply}else{reply.progress()}).scope(&mut self.advance_route,key)?;let inner=OriginalEffectReply::borrow(&mut self.copy_reply)?;let done=if publish{self.prefix.publish_into(&mut self.output,effect,inner)}else{let copy=T::native_copy().ok_or_else(||ValueError::literal(ValueRefusalKind::UnsupportedOwner,"array child producer is not yet available"))?;if whole{copy.array_into(source.get(),&mut self.output,effect,inner)}else{copy.prefix_into(source.get(),&mut self.prefix,count,effect,inner)}}?;drop(done);let forwarded=forward_original_value_reply(&mut self.copy_reply,scope.borrow()?)?;drop(forwarded);Ok(scope.forwarded())
    }
    fn recover_advance_into<'reply>(&mut self,source:RetainedCloneRef<'_,[T;N]>,body:usize,maximum:u64,_effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{let (identity,index,original_body,original_maximum,source_id)=self.advance_route.ok_or_else(||ValueError::invariant("array original advance is absent"))?;if (body,maximum,source.reference_identity())!=(original_body,original_maximum,source_id)||self.copy_reply.is_none()&&self.prefix.initialized()!=index{return Err(ValueError::invariant("array original advance request changed"))}let invocation=_effect.invocation().ok_or_else(||ValueError::invariant("array recovery requires original invocation"))?;if invocation.identity()!=identity||invocation.mode()!=crate::OriginalEffectCallbackMode::Recover{return Err(ValueError::invariant("array original recovery invocation changed"))}let progress=self.copy_reply.as_ref().is_some_and(|result|matches!(result,Ok(RetainedCloneStep::Progress(_))));let mut scope=(if progress{reply.progress()}else{reply}).scope(&mut self.advance_route,(identity,index,original_body,original_maximum,source_id))?;let done=forward_original_value_reply(&mut self.copy_reply,scope.borrow()?)?;drop(done);Ok(scope.forwarded())}
    fn output_ready(&self) -> bool { !self.closing && !self.spent && self.output.is_some() && self.advance_route.is_none() && self.copy_reply.is_none() }
    fn close_started(&self) -> bool { self.closing }




    fn advance_demands(&self,source:RetainedCloneRef<'_,[T;N]>,body:usize,maximum:u64)->Result<RetirementDemand,ValueError>{
        if self.closing||self.spent{return Err(ValueError::invariant("array clone is closing or spent"))}if maximum==0||self.output_ready(){return Ok(Default::default())}if let Some(demand)=source.binding_demand(&self.source)?{return Ok(demand)}if self.prefix.initialized()==N{return NativeArrayPrefix::<T,N>::publication_demand()}if self.child.is_some()||self.child_value.is_some(){return Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"array child producer is not yet available"))}let copy=T::native_copy().ok_or_else(||ValueError::literal(ValueRefusalKind::UnsupportedOwner,"array child producer is not yet available"))?;if self.whole_copy(body){return copy.array_demand::<N>()}let selected=self.prefix_selection(body,maximum)?;if selected.elements==0{return Ok(Default::default())}copy.prefix_demand(selected.elements)
    }
    fn advance_work_demand(&self,source:RetainedCloneRef<'_,[T;N]>,body:usize,maximum:u64)->Result<u64,ValueError>{
        if self.closing||self.spent{return Err(ValueError::invariant("array clone is closing or spent"))}if maximum==0||self.output_ready(){return Ok(0)}let check=RetainedCloneRef::<[T;N]>::check_binding_work(&self.source);let action=if self.source.is_none(){source.binding_work_demand(&self.source)?}else if self.prefix.initialized()==N{1}else{if self.child.is_some()||self.child_value.is_some(){return Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"array child producer is not yet available"))}let copy=T::native_copy().ok_or_else(||ValueError::literal(ValueRefusalKind::UnsupportedOwner,"array child producer is not yet available"))?;if self.whole_copy(body){copy.array_work::<N>()?}else{let selected=self.prefix_selection(body,maximum)?;if selected.elements==0{return Ok(0)}copy.prefix_work(selected.elements)?}};let work=check.checked_add(action).ok_or_else(||ValueError::invariant("array original work quote overflow"))?;Ok(if work<=maximum{work}else{0})
    }
 fn begin_close_into<'reply>(&mut self,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{let turn=self.begin_close_paid(effect);Ok(reply.complete(turn.result.map(RetainedCloneStep::Progress).map_err(Into::into)))}
 fn recover_begin_close_into<'reply>(&mut self,_effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{Ok(reply.pending())}
    fn take_work_demand(&self)->Result<u64,ValueError>{Ok(u64::from(self.output_ready()))}
    fn begin_close_work_demand(&self)->Result<u64,ValueError>{Ok(u64::from(!self.closing))}
    fn begin_close_demand(&self)->Result<crate::RetirementDemand,crate::ValueError>{let flags=usize::from(!self.closing);Ok(crate::RetirementDemand{copy_bytes:flags*std::mem::size_of::<bool>(),depth:usize::from(flags!=0),..Default::default()})}
fn begin_close_paid(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::RetainedWorkOutcome<crate::RetainedCloneProgress,crate::ValueError>{crate::retained_clone::start_retained_close(&mut self.closing,effect)}
    fn take_demand(&self)->Result<RetirementDemand,ValueError>{crate::retained_clone::retained_clone_cursor_take_demand::<[T; N],bool>()}
    fn take<'reply>(&mut self,output:&mut Option<[T; N]>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetainedCloneStep,ValueError>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetainedCloneStep,ValueError>,ValueError>{crate::retained_clone::take_retained_clone_cursor_output!(self.output_ready(),*self.output,output,self.spent,true,effect,reply,[T; N],bool)}

    

    fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{if self.close_route.is_some_and(|(_,_,selected,_)|selected!=body){return Err(ValueError::invariant("cursor close query changed original body"))}if !self.closing{return Ok(0)}if let Some(child)=self.child.as_ref(){if !self.child_closing{return child.begin_close_work_demand()}return if child.terminal_is_empty(){Ok(1)}else{child.close_work_demand(body)}}if !self.close.is_empty(){return self.close.next_owner_work::<[T;N]>(false,&self.source,body)}if self.child_value.is_some(){return self.close.next_owner_work::<T>(true,&self.source,body)}if self.prefix.initialized()>0{return Ok(1)}self.close.next_owner_work::<[T;N]>(self.output.is_some(),&self.source,body)}
    fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.close_route.is_some_and(|(_,_,selected,_)|selected!=body){return Err(ValueError::invariant("cursor close query changed original body"))}if !self.closing{return Ok(Default::default());}
        if let Some(child)=self.child.as_ref(){if !self.child_closing{return child_close_start_demand(child);}return if child.terminal_is_empty(){Ok(RetirementDemand{copy_bytes:size_of::<T::Cursor>(),depth:1,..Default::default()})}else{nested_retained_clone_close_demands::<T>(child,body)};}
        if !self.close.is_empty(){return self.close.next_owner_demands::<[T;N]>(false,&self.source,body);}
        if self.child_value.is_some(){return self.close.next_owner_demands::<T>(true,&self.source,body);}
        if !self.prefix.is_empty(){return NativeArrayPrefix::<T,N>::element_demand();}
        self.close.next_owner_demands::<[T;N]>(self.output.is_some(),&self.source,body)}
    fn next_close_depth_demand(&self)->Result<usize,ValueError>{Ok(self.close_demands(0)?.depth)}
    fn next_close_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(self.close_demands(0)?.copy_bytes)}
    fn next_close_capacity_byte_demand(&self,body:usize)->Result<usize,ValueError>{Ok(self.close_demands(body)?.capacity_bytes)}
    fn next_close_release_byte_demand(&self)->Result<usize,ValueError>{Ok(self.close_demands(0)?.release_bytes)}
    fn terminal_is_empty(&self) -> bool { self.closing && self.child.is_none() && self.child_value.is_none() && self.output.is_none() && self.prefix.initialized() == 0 && self.close.is_empty() && self.source.is_none() && self.close_route.is_none() && self.advance_route.is_none() && self.copy_reply.is_none() }
}

impl<T:RetainedClone,const N:usize> Drop for ArrayCursor<T,N> {
    fn drop(&mut self) { assert!((self.prefix.initialized()==0 && self.child.is_none() && self.child_value.is_none() && self.output.is_none() && self.source.is_none() && self.close.is_empty() && self.close_route.is_none() && self.advance_route.is_none() && self.copy_reply.is_none()) || std::thread::panicking(),"array clone dropped before original owner closure"); }
}

impl<T: RetainedClone, const N: usize> RetainedClone for [T; N] {
    type Cursor = ArrayCursor<T, N>;
    fn retained_clone_cursor() -> Self::Cursor { ArrayCursor::default() }
    fn native_copy()->Option<RetainedCopy<Self>>{T::native_copy().map(|copy|copy.array_witness::<N>())}
}
